// Helper: convert a Python object to a contiguous double C array.
// Returns a malloc'd pointer, or NULL on failure (with exception set).
static double* get_double_array(PyObject* obj, int expected_ndim, int* out_n) {
    if (!PyArray_Check(obj)) {
        PyErr_SetString(PyExc_TypeError,
                        "expected a NumPy array (or object convertible to one)");
        return NULL;
    }
    // np.ascontiguousarray(arr, dtype=np.float64): safe copy, guarantees
    // C-contiguous float64 layout regardless of input dtype/contiguity.
    PyObject* converted = PyArray_FROM_OTF(obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (converted == NULL) {
        return NULL;
    }
    PyArrayObject* arr = (PyArrayObject*)converted;
    if (PyArray_NDIM(arr) != expected_ndim) {
        Py_DECREF(converted);
        PyErr_Format(PyExc_ValueError,
                     "expected an array with %d dimensions, got %ld",
                     expected_ndim, (long)PyArray_NDIM(arr));
        return NULL;
    }
    npy_intp n = PyArray_SHAPE(arr)[0];
    double* data = (double*)PyArray_DATA(arr);
    *out_n = (int)n;
    // NOTE: caller owns the converted array and must Py_DECREF it.
    // We leak the reference on purpose here to keep the data alive? NO -
    // instead the caller must keep the converted object alive until done.
    return data;
}

