// Extract a C pointer to the elements of a 1-D sequence of doubles.
// need_free: 0 = data points into the input array;
//            1 = data points into *holder (a new array; DECREF to release);
//            -1 = data is a malloc buffer (free() to release).
// Returns 1 on success, 0 on failure (exception set).
static int get_1d_doubles(PyObject* obj, int* out_n, double** out_data,
                          PyObject** holder, int* need_free) {
    *need_free = 0;
    *out_data = NULL;
    *out_n = 0;
    *holder = NULL;

    if (PyArray_Check(obj)) {
        PyArrayObject* arr = (PyArrayObject*)obj;
        if (PyArray_NDIM(arr) == 1 &&
            PyArray_TYPE(arr) == NPY_DOUBLE &&
            PyArray_IS_C_CONTIGUOUS(arr) &&
            PyArray_ITEMSIZE(arr) == 8) {
            *out_n = (int)PyArray_DIM(arr, 0);
            *out_data = (double*)PyArray_DATA(arr);
            return 1;
        }
        PyObject* conv = PyArray_FROM_OTF(obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (conv == NULL) {
            return 0;
        }
        PyArrayObject* carr = (PyArrayObject*)conv;
        if (PyArray_NDIM(carr) != 1) {
            Py_DECREF(conv);
            PyErr_SetString(PyExc_ValueError, "expected a 1D array");
            return 0;
        }
        *out_n = (int)PyArray_DIM(carr, 0);
        *out_data = (double*)PyArray_DATA(carr);
        *holder = conv;
        *need_free = 1;
        return 1;
    }

    if (PySequence_Check(obj)) {
        Py_ssize_t len = PySequence_Length(obj);
        if (len < 0) {
            return 0;
        }
        double* buf = (double*)malloc((size_t)len * sizeof(double));
        if (buf == NULL) {
            PyErr_NoMemory();
            return 0;
        }
        Py_ssize_t i;
        for (i = 0; i < len; i++) {
            PyObject* item = PySequence_GetItem(obj, i);
            if (item == NULL) {
                free(buf);
                return 0;
            }
            double v = PyFloat_AsDouble(item);
            Py_DECREF(item);
            if (v == -1.0 && PyErr_Occurred()) {
                free(buf);
                return 0;
            }
            buf[i] = v;
        }
        *out_n = (int)len;
        *out_data = buf;
        *need_free = -1;
        return 1;
    }

    PyErr_SetString(PyExc_TypeError,
                    "expected a 1D sequence or array of numbers");
    return 0;
}

static void release_1d_doubles(double* data, PyObject* holder, int need_free) {
    if (need_free == 1) {
        Py_DECREF(holder);
    } else if (need_free == -1) {
        free(data);
